INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти оириш даракчӣ (дерепоӣ) дар парвариши маш</h2>\n<p>Маш яке аз муҳимтарин ҳобҳои зудпояндароки кишоварии Эрон аст, ки ба сабаби давоми кӯтоҳи афзоиш, фоидаи иқтисодии бомуътабарро барои деҳқонон ба вуҷуд меорад. Бо вуҷуди аҳамияти об дар иқтисодиёти кишоварӣ, истифодаи усулҳои анъанавии оириши пашуни (спринклерӣ) ба талафоти энергия ва тарбуҳи физиологӣ дар наботот оварда мерасонад. Дар ин байн, системаҳои оириши зери фишор монанди оириши даракчӣ (дерепоӣ) ва нӯҳари тип (ластук) ҳалли ҳосилҳои муосир мебошанд, ки имконияти идоракунии дақиқи захираҳои обро фароҳам меоранд. Оириши даракчӣ барои маш на танҳо истеъмолро то 50 фоиз кам мекунад, балки бо тоҷҳол кардани минтақаи решаҳо ва хушк мондани сатҳи хок, паҳншавии бемориҳои қарози пӯстӣро ба ҳадди ақал мерасонад. Дар ин мақола, мо дар бораи чӣ гуна ҷорӣ кардани дақиқи он <strong>оириши даракчӣ барои маш</strong> ва баррасии барномаи мусоид барои ҳар марҳилаи афзоиш сару садо мекунем, то ки метавонед аз тамоми имкониятҳои ин технология фоида бардоред.</p>\n\n<h2>Асосҳои кишоварӣ ва омодагии омор (земай) дар системаи даракчӣ</h2>\n<p>Муваффақият дар оириши маш аз лаҳзаи омодагии замин оғоз меёбад. Пеш аз кишоварӣ, замин бояд пурра чалғонида (шакмронӣ) ва решакашонӣ шуда бошад, то хок тозиқшаванда ва нарм шуда бошад. Гузоштани ҳарорати ниҳогӣ бо ҳарорати озод ва минералӣ низ дар ин марҳила муҳим аст. Нуқтаи муҳим дар системаҳои даракчӣ "масофаи кишоварӣ" ва ҷойгиршавии ҷурғунҳо аст. Маш одатан дар ҷурғунҳои зичи кишт мешавад. Маслиҳат карда мешавад, ки масофаи ҷурғунҳо ба андозаи 40 то 50 сантиметр танзим карда шавад, то нӯҳари тип ё қубури даракчӣ тавонад бо тартибот дар поён ё паҳлӯи ҷурғунҳо ҷойгир шавад. Ин ҷойгиршавӣ имкон медиҳад, ки об ба таври мустақим ба минтақаи решаҳо расад ва талафоти об ба сабаби таҳор (бӯм шудан) аз сатҳи хок кам шавад. Барои фаҳмиши беҳтари асосҳои умумии ҷойгиршавии наботот дар хатҳои оириш ва идоракунии расонидани об, омӯзиши миқдори гирифти ҳавоӣ дар ҳектар метавонад диди иловагӣ аз муҳайякунии захираҳо дар мавҷотро пешниҳод кунад.</p>\n\n<h2>Барномаи оириши маш дар марҳилаҳои гуногуни афзоиш</h2>\n<p>Маш набототе мебошад, ки давоми кӯтоҳи афзоиш (тоқ. 50 то 60 рӯз) ва ҳаросатнокӣ нисбӣ ба тарбуҳи обӣ дар рӯзҳои гулгӣ ва ташаккули дучаш дорад. Барномаи оириш бояд бар асоси ниёзи рӯзи наботот ва шароити иқлимии минтақа танзим шавад. Ба таври умумӣ, дар оириши даракчӣ, об бо оромӣ ва дар ҳаҷмҳои кам, вале бозу-гаштӣ рехте мешавад, то ки хушкӣ байни оиришҳо баромада намандашад. Идоракунии дурусти об дар ҳар фазаи афзоишӣ, бевосита ба вазни дучаш ва натиҷаи ниҳоӣ таъсир мерасонад.</p>\n\n<h3>Марҳилаи насбӯд ва афзоиши аввалия</h3>\n<ol>\n<li>Дар 5 рӯзи аввали баъд аз кишоварӣ, оиришҳои сабук ва кӯтоҳ (10 то 15 дақиқа) ҳаррӯза ё ҳар ду рӯз якбор маслиҳат карда мешавад, то ки дучашҳо ба намноки якхела расанд ва раванди насбӯди фаъол шавад.</li>\n<li>Бо пайдо шудани наботот аз сатҳи замин, зарур аст, ки маддат (вақти) оириш пайдарпай зиёд карда шавад, то ки решаҳои иловагӣ пурра ташаккул ёбанд.</li>\n</ol>\n\n<h3>Марҳилаи афзоиши вегетативӣ</h3>\n<p>Дар ин марҳила, ки дар бар гирифтани пайдои баргҳо ва пур шудани боғ аст, талаботи наботот ба об зиёд мешавад. Барориши оириш метавонад ҳар 2 то 3 рӯз якбор бо маддати 20 то 30 дақиқа бошад. Дараҷаи воридшавии решаҳо дар ин давра бештар аст ва хок бояд тозмонда монда бошад. Барои фаҳмиши беҳтари ниёзҳои обӣ дар шароитҳои гуногуни иқлимӣ ва устувории системаҳо, омӯзиши масофаи нӯҳари тип барои гандум ва усулҳои нав оириш метавонад диди иловагиро аз танзимоти масофагузорӣ ва сарпӯши дар маҳсулоти дигар диҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ماش-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت ماش با آبیاری قطره‌ای - تصویر 1"/><figcaption>usullarai kishovarii oirishi darakchi shomaliya-i mash</figcaption></figure>\n\n\n<h3>Марҳилаи гулгӣ ва ташаккули мева</h3>\n<ul>\n<li>Даромади ҳаросатноктарин ба тарбуҳи обӣ ин марҳила аст. Гиромарги хушкӣ метавонад ба кам шудани вазни боғ ва сифати ниҳоии дучаш оварда расонад.</li>\n<li>Оириш бояд бо тартибот (ҳар 1 то 2 рӯз якбор) бошад, то ки парешоги гандуми дучаш пешгири шуда бошад.</li>\n<li>Шиддати сарпӯши нохалҳо метавонад каме зиёд шавад, то ки фишори решаҳо рӯй ба хок барои шикастани қабати сатҳӣ ва ҷидоби беҳтари моддаҳои ғизоӣ нигоҳ дошта шавад.</li>\n</ul>\n\n<h3>Марҳилаи пухтани ва омодагии барои харидан</h3>\n<p>Тақрибан як ҳафта пеш аз харидан, обёрӣро қатъ кунед. Ин кор боиси афзоиши ҷамъшавии қанд дар донаҳо ва хушкшавии мувофиқи гиёҳ мегардад, ки дар коркарди саноatii машҳум муҳим аст. Барои муқоиса бо дигар дунбулоҳо ва фаҳмиши беҳтари зичии партофтобӣ, мақола <a href="https://navar-abyari.ir/pea-seed-quantity-per-hectar-iraq/">Миқдори бодаи нуҳут дар гектар</a> Маълумоти иловагӣ дар бораи таваҷҷӯҳҳои монанди ин гурӯҳи маҳсулотро пешниҳод мекунад.</p>\n\n<h2>Нуқтаҳои амалӣ ва идоракунии системаи лентаи пайваст</h2>\n<p>Истифодаи лентаи пайваст барои машҳум, баъди ҳама дар боғҳои бо андозаи бузург, самаранокӣ баланд дорад. Лентаи пайваст ба фарқ аз қатравии инфиродӣ, шикофаҳои тарриро дар тӯли худ дорад, ки обро бо якдунӣ дар тӯли садҳо реліз мекунад. Ин усул барои машҳум, ки дар садҳои муштараҳ партофта мешавад, идеалӣ аст. Вақти насбкардан, ҳатман лентаро чунон ҷойгир кунед, ки аз маркази сад дар болои хок ҷойгир шавад ва аз баччаҳои чӯбӣ ё сим истифода баред, то ки бод онро ҷунбонад. Агар аз қатравии инфиродӣ истифода баред, назларо бо масофаи 20 то 30 сантиметр аз ҳам дар тӯли лӯла ҷойгир кунед, то ки пошши якдуниро ба вуҷуд орад.</p>\n\n<h3>Паҳмонидан аз банд шудани назлҳо</h3>\n<p>Машҳум гиёҳест, ки решаҳои хурди он метавонад ба кӯдакҳои хурди назлҳо наздик шавад. Инчунин ҷамъшавии намакҳо дар хокҳои намакдор метавонад бандшавиро ба вуҷуд орад. Истифодаи филтри дискии ё симии бо 120 то 150 азимат зарур аст. Инчунин тавсия дода мешавад, ки системаи шустушӯи рӯзаро дошта бошед, то ки ҷамъшавиҳо аз дохили лӯла берун шаванд. Агар дар минтақае бо оби сахт зиндагӣ кунед, шӯридан бо мутахассисон дар бораи илова намудани моддаҳои кислотакунанда барои пешгирӣ аз ҷамъшавии калсий зарур аст. Барои дидани намунаи дигари татбиқшуда аз системаҳои нав барои маҳсулоти дунбулӣ ва зардӣ, метавонед ба <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%a2%d8%ac%db%8c%d9%84%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Сатҳи ҳосилдоҳии кдуи аҷивӣ дар гектар бо истифода аз лентаи пайваст</a> нигаред, ки ишорагари устувории ин усул дар дигар маҳсулот аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ماش-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت ماش با آبیاری قطره‌ای - تصویر 2"/><figcaption>planting methods drip crop irrigation schedule машҳум</figcaption></figure>\n\n\n<h2>Саволҳои одад (FAQ)</h2>\n\n<h3>Оё метавон аз ҳамон системаи қатравии гандум барои машҳум истифода бард?</h3>\n<p>Сохтори умумии лӯлаҳо яксон аст, аммо параметрҳои қавм ва масофаи назлҳо тағйир меёбад. Масофаи назлҳои гандум одатан зиёдтар аст. Барои машҳум, ки зичии партофтобӣ баланд дорад, ба талаботи бештари назлҳо ниёз доред. Бинобар ин, танзимот бояд дар системаи нав ё бозсозии системаи пешина анҷом шавад, то аз зарари решаҳои машҳум пешгирӣ кунад.</p>\n\n<h3>Беҳтарин вақти насб кардани лентаи пайваст барои машҳум чӣ вақт аст?</h3>\n<p>Лентаи пайвастро метавон ҳангоми партофтани бода ҳамзамон кор кард, то ки хароҷоти корӣ камтар шавад, аммо бояд диққат дод, ки лента дар зери хок ҷойгир навад ва аз хатогии ҷойгиршавӣ пешгирӣ карда шавад. Беҳтар аст, ки пас аз шикмзани ва пеш аз партофтани, лентаро дар рӯи хок ё дар таҳти кам (5 сантиметр) пӯшонед, то ки дар дастрасии решаҳои ибтидоӣ бошад.</p>\n\n<h3>Оё гузаштани куд дар ҳолои обёрӣ бо усули қатравӣ (кудшуӣ) барои машҳум тавсия дода мешавад?</h3>\n<p>Бале, худшуӣ яке аз фоидаҳои асосии қатравӣ аст. Аммо бояд аз кудҳои сахт бо эҳтиёт истифода баред. Кудҳои маҳлулӣ бо консентратсияҳои мувофиқ (масалан, 5-10 грамм бар литр) дар соатҳои хунуктар инкишоф диҳанд. Аз ҳамзамонии паҳши куд ва обкории лентаи пайваст парҳез кунед, ғайр аз он ки системаи шустушӯи қавӣ доред, то аз ҷамъшавӣ дар дохили лӯла пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ماش-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت ماش با آبیاری قطره‌ای - تصویر 3"/><figcaption>усулҳои гулидан кардани набототи шолӣ, реҷаи обориши тамға</figcaption></figure>\n\n\n<h2>Хулоса</h2>\n<p>Иҷрои дурусти обориши тамға дар кӯлтоки шолӣ, калиди расидан ба ҳосили якхела, солим ва бо самаранокии иқтисодии баланд аст. Бо риояи фосилаҳои мувофиқи гуло, танзими дақиқи барномаи обориш мувофиқи марҳалаҳои афзоиш ва нигоҳубини система, шумо метавонед аз фишори об ва бемориҳо пешгирӣ кунед ва самаранокии обро ба ҳадди аввал барсонед. Ин усул на танҳо муҳити зист, балки барои ҷайби деҳқоён низ хеле бузорӣ аст. Ошноӣ ба ин техникаҳо, асоси кишоварзии дақиқ ва давомдор дар минтақаҳои камобии Эрон аст.</p>\n<p><strong>Маълумоти вобаста:</strong> Фосилаи навори тип гандум ва усулҳои нав обориш, <a href="https://navar-abyari.ir/ushuli-shinodani-piyaz-obri-nuqravi/">uswali shinodani piyaz obri nuqravi</a></p>\n<p><strong>Маълумоти вобаста:</strong> <a href="https://navar-abyari.ir/%d9%81%d8%a7%d8%b5%d9%84%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%da%af%d9%86%d8%af%d9%85-%d8%af%d8%b3%d8%aa%da%af%d8%a7%d9%87-%d8%b2%d9%85%d8%a7%d9%86-%d8%aa%d8%b9%d8%af%d8%a7%d8%af/">Фосилаи навори тип гандум ва усулҳои нав обориш</a></p>','Комиллони ғамхӯраи ғӯлӣ бо обёрӣ-е нӯкиш ва навъи Tippe','Дар ин дастураи оммақвор, мо принсипҳои карди моҳиро бо истифода аз ободории боқатмониву тасмавӣ, нақшаи вақти ободорию нуқтаҳои муҳим барои зиёд кардани намнокиро баррасӣ мекунем.','publish','closed','closed','komsili-zar-i-bobi-kabud-i-drop-i-navi-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
