INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل زراعة الكراث بالري بالتنقيط AFP | إرشادات فلاحية احترافية للعراق' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على أفضل ممارسات زراعة الكراث باستخدام أنظمة الري بالتنقيط AFP. دليل عملي موجه للمزارعين العراقيين لزيادة العوائد وتقليل الفاقد مع نصائح فنية دقيقة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
