INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар муҳимияти оборӣи муосир дар парҳези сарсоми</h2>\n<p>Сарсоми яке аз маҳсулоти ҳазирнок ва барг дор аст, ки дар тамоми Эрон ва ҷаҳон парҳез мешавад. Ин гиёҳ дар фаслҳои рушд нисбат ба таъминоти кӯтоҳии об ва фишорҳои муҳит иҳотагӣ ҳаст. Истифодаи усулҳои анъанавии оборӣи ғариқӣ на танҳо боиси талафоти шадиди манбаъҳои об мегардад, балки метавонад ба бемориҳои қарозӣ ва пӯсиши реша оварда расонад. Дар навбат,  <strong>оборӣи тақтилии сарсоми</strong> дар шакли пилонка, имконияти дақиқро барои парокандашавии намӣ дар минтақаи реша фароҳам меорад. Ин усул бо нигоҳдории устувории намии хок, рушди якҷояи ботҳо ва зиёд шудани ҳаҷми ботҳо ҳосил мекунад. Дар давом додани ин мавзӯъ, мо қадам ба қадам роҳнамоии парҳез ва оборӣи сарсомиро баррасӣ мекунем.</p>\n\n\n\n<h2>Усулҳои парҳез ва ҷобаҷогузории қисмҳои рушди сарсоми</h2>\n<p>Барои истифодаи максималии системаҳои муосири оборӣ, тарзи парҳези сарсоми муҳимияти ҳатмӣ дорад. Сарсоми тавассути парҳези кӯбӣ ё тохм парҳез мешавад, аммо усули кӯбӣ (истифода аз кӯбҳо ё қисмҳои рушд) бо сабаби зудӣ дар рушд, дар парҳезҳои саноатӣ паҳншуда аст. Масофаи байни парҳез бояҳ бо намуди хок ва нӯви системаи оборӣ мутобиқ бошад.</p>\n<h3>Масофагузории мувофиқ барои пилонка</h3>\n<ul>\n<li><strong>Масофаи байни қаторҳо:</strong> Одатан аз 40 то 50 сантиметр тавсия дода мешавад, то имконияти гузариши пилонка ва дастрасӣ ба ботҳо нигоҳ дошта шавад.</li>\n<li><strong>Масофаи байни ботҳо:</strong> Масофаи 15 то 20 сантиметр дар қатор зичии мувофиқро ба вуҷуд меорад ва аз таъсири баргҳо ба ҳарҷоягӣ пешгирӣ мекунад.</li>\n<li><strong>Самти парҳез:</strong> Беҳтар аст қаторҳо самти шимоли-Ҷануб бошанд, то таркиби рӯшноӣи мувофиқ барои рушди якҷояи сабзиҳо эҷод шавад.</li>\n</ul>\n<p>Нуқтаи муҳим дар парҳез ин аст, ки кӯбҳо бояҳ тақрибан дар чуқурии 5 то 7 сантиметр дар хок ҷойгир карда шаванд. Ин чуқурӣ боиси шудани зудтар рушди реша мегардад ва бот ба шидат ва хушкӣ тобовартар мешавад. Дар ҳолати истифода аз тохм, ба сабаби ниёз ба ҳароратҳои сардтар барои пӯшедан, беҳтар аст аз парҳез дар охирҳои моҳи май ё аввали моҳи июн истифода шавад. Барои шиносӣ бо принсипҳои умумии ҷобаҷогузорӣ дар парҳезҳои тохмӣ ва муқоиса бо парҳези сарсоми, метавонед ба <a href="https://navar-abyari.ir/mikdori-tuxmi-qadu-dar-yak-gektar-omilhoyi-tasirrasoni-zichi/">тадқиқи миқдори қаламӯсу сабабҳои таъсиррасонанда ба зичӣ</a> ҳам диққат диҳед, то фарқиятҳои идоракунии зичӣ дар маҳсулот гуногунро фаҳмед.</p>\n\n<h2>Тарроҳӣ ва насби системаи пилонка барои сарсоми</h2>\n<p>Пилонка яке аз самараноктарин ва арзонтарин усулҳои <strong>Ориёшӣ тақчӣ</strong> ки махсусан бар сабзавот ва маҳсулоти қаторӣ, ба монанди мошӯр, афзалиятнок аст. Ин низоми аз як навбари пластики қалитар, нисбат ба ориёшкунандаи тақчӣ муқаррарӣ, иборат аст, ки аз он қатраҳои об бо фосилаҳои муайян (масалан, ҳар 20 сантимиетр) берун меоянд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-موسیر-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت موسیر با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кишткори ориёишӣ тақчӣ барномаи ориёшӣ моди мошӯр</figcaption></figure>\n<h3>Параметрҳои техникии мувофиқ</h3>\n<ol>\n<li><strong>Дурнамоӣкунандаҳо:</strong> Фосилаи 20 то 40 сантимиетр байни дурнамоӣкунандаҳо вобаста ба хурд ё калон будани бодирҳо мувофиқ аст.</li>\n<li><strong>Суръати оҳанг:</strong> Барои мошӯр, навбарҳое, ки дар ҳар дурнамоӣкунанда 1/6 ё 2 литр дар соат доранд, тавсия дода мешаванд.</li>\n<li><strong>Шумораи навбарҳо:</strong> Одатан як навбар ба андозаи паҳнои қаторӣ дар сатҳи хок ҷойгир карда мешавад ё ду навбар бо фосилаи 10-15 сантимиетр аз маркази қаторӣ.</li>\n</ol>\n<p>Насб кардани навбари ориёшӣ бояд ҳамзамон бо кишткор сурат гирад. Дар усулҳои муосир, навбари ориёшӣ ба сурати зерзаминӣ ё дар сатҳи хок паҳн карда мешавад. Агар навбар дар сатҳ бошад, пас аз кишт, онро бо хок ё пӯсти ордӣ пӯшонед, то аз бозунии тез таркиш ва корхӯрии навбар тарафи ҳайвонот пешгирӣ шавад. Раҳнамоии васеътар барои интихоб ва насби навбарҳои ориёишӣ дар манбаи ихтисосӣ дастрас аст, ки метавонад дар интихоби қисмҳои ивазкунандаи низоми шумо комёб бошад.</p>\n\n\n\n<h2>Барномагузории ориёшӣ тақчӣ дар асоси марҳилаҳои рушднокӣ</h2>\n<p>Қисми муҳимтарини идоракунии ориёшӣ, дарки ниёз ба об барои мошӯр дар ҳар марҳилаи рушд аст. Ориёши зиёд боиси партофани қалмоҳо ва бемориҳои занворӣ мешавад ва ориёши кам низ боиси хурд шудани буттаҳо ва кам шудани вазни маҳсул мегардад.</p>\n<h3>Марҳилаҳои ҳассос ба об</h3>\n<table border="1" cellpadding="5" cellspacing="0">\n<tr>\n<th>Марҳилаи рушднокӣ</th>\n<th>Нуқтаҳои асосӣ</th>\n<th>Тавсияи ориёшӣ бо навбар</th>\n</tr>\n<tr>\n<td>Моддикушӣ то баргузоршӣ (ҳафтаҳои 1-2 аввал)</td>\n<td>Парастории рағбатнокӣ барои решагурии пиёзлаҳӯҷум</td>\n<td>Обёркуни кӯтоҳ ва такроршуда, рӯзона 2 то 3 маротиба бо давомнокии 15-20 дақиқа.</td>\n</tr>\n<tr>\n<td>Баррасии тези бут (3-6 ҳафта)</td>\n<td>Тақсимоти баробари рағбатнокӣ дар чуқурии 30 сантиметр</td>\n<td>Ҳар 2 то 3 рӯз як маротиба, бо давомнокии 45-60 дақиқа.</td>\n</tr>\n<tr>\n<td>Охири мавсими растанӣ (2 ҳафта пеш аз гармонидан)</td>\n<td>Ҷамъовии ва зиёдшавии шаҳомати баргҳо</td>\n<td>Кушодани пурраи обёркунӣ ба давомнокии 10 то 14 рӯз пеш аз гармонидан.</td>\n</tr>\n</table>\n<p>Тағйироти қуллаҳои боронӣ дар системаи найчаи каптӣ пайкардани сода дорад. Бо кам кардани фишори воридотӣ ё кам кардани шумораи найчаҳои фаъол, метавон рағбатнокӣ-ро ба ҳадди ақал акад. Барои фаҳмиши беҳтари дараҷаи рағбатнокӣ ва сарфариши ниҳоӣ, таҳқиқот <a href="https://navar-abyari.ir/sugar-beet-yield-per-hectare-factors/">Омилҳои зиёдкуни сарфариши чӯкандасунбук</a> метавонад муфид бошад, зеро ҳарду меҳвоҷот аз нишониди рафтори решагӣ ва ниёз ба пуррашавии дар охири мавсим монанди назаррас доранд.</p>\n\n<h2>Нуқтаҳои амалӣ барои зиёдшавии сарфариш ва камкунии хараҷот</h2>\n<p>Идоракунии оқилонаи обёркунӣ, сарфаи зиёд дар хараҷоти истеҳсолотро ба оварда мерасонад. Дар пухти пиёзлаҳӯҷум бо найчаи каптӣ, чунин чизҳоро ба назар гиред:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-موسیر-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت موسیر با آبیاری قطره‌ای - تصویر 2"/><figcaption>usuli kiшт kapti oborkunii jadvali makhsoj</figcaption></figure>\n<ul>\n<li><strong>Обёркунӣ бо ғизонок (Фертигатион):</strong> Пиёзлаҳӯҷум ба кӯдҳои нитрогенӣ хуб посух медиҳад. Ин моддаҳоро метавон мустақиман аз тавассути системаи найчаи каптӣ ба решаҳо тиррезӣ кард. Ин кор боиси зиёдшавии сарфаи ҷидиби кӯдҳо то 30 вазид мешавад. Барои муқоиса бо пухтҳои бодӣ, даромади миқдори биҳиши қубатқушҳо дар гектар нишон медиҳад, ки чунин чӣ қадар тафовут доштан метавонад, аммо дар пиёзлаҳӯҷум, сифати бут аз шумора муҳимтар аст.</li>\n<li><strong>Пӯшиш бо қамчир ё малчс:</strong> Истифода аз қамчир ё тӯрҳои махсус барои бастари пухт, ҳарорати хокро танзим мекунад ва ниёз ба обёркуниро кам мекунад.</li>\n<li><strong>Мониторинги ғалаи хок:</strong> Аз сенсорҳои ғала истифода баред. Ғалаи муносиби решаҳои сарсоми тақрибан аз 60 то 70 фоизи ғаламундат (field capacity) аст.</li>\n</ul>\n\n\n\n<h2>Ҷавоб ба саволҳои оддӣ (FAQ)</h2>\n<p><strong>Савол 1: Оё системаи нафари барои сарсоми беҳтар аз қатразанҳои ягона аст?</strong>\nБале, зеро сарсоми мҳсулоти қаторӣ аст ва нафари пӯшиши равшантарро таъмин мекунад ва хароҷот камтарро дорад. Қатразанҳои ягона одатан барои дарахтонкунӣ тавсия дода мешаванд.</p>\n<p><strong>Савол 2: Чӣ қадар муҳим аст, ки пеш аз ҷамоварии сарсоми обёрро қатъ кунем?</strong>\nКамин 10 то 14 рӯз пеш аз ҷамоварӣ обёро пурра қатъ кунед. Ин кор боиси мустаҳкам гардидани решаҳо ва сарсанги бугнудёфтаи сарсоми мешавад ва фоизи ширинӣ ва моддаҳои озувиро баланд мебардорад. Ғайр аз ин, боқимондани сарсоми дар харубон беҳтар мешавад.</p>\n<p><strong>Савол 3: Агар шӯрҳои зиёд вуҷуд дошта бошад, системаи нафари чӣ гуна зарар мебинд?</strong>\nДаст нарезидан ба нафарҳо ҳангоми кор бо шӯр ва истифода аз торҳои муҳофизотӣ ё гузаштан болои нафар ҳангоми кор, аз зарари физикӣ пешгирӣ мекунад. Ғайр аз ин, шустани давомноки система (Flushing) дар охир ҳар обёр тавсия мешавад, то ки афзоишҳо ҷамъ набошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-موسیر-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت موسیر با آبیاری قطره‌ای - تصویر 3"/><figcaption>рӯйхати ҷои ғаламандӣ методҳои нафари сабури сарсоми ҳисоби обёр</figcaption></figure>\n<p><strong>Савол 4: Оё аз системаи нафари барои дигар наботот чун нӯхӯд ё ғӯлӣ ҳам истифода кардан мумкин аст?</strong>\nБале, аммо тарҳбандии фосилаи байни қатразанҳо бояд тағйир ёбад. Барои мисол, дар катон кардани ғӯлӣ ё дигар ғалладониҳо, фосила байни буттаҳо кӯтоҳтар аст ва бинобар ин нафар бо фосилаҳои зич (масалан, 15 сантиметр) мувофиқтар аст.</p>\n\n<h2>Хулоса</h2>\n<p>Истифодаи <strong>обёри қатрагии сарсоми</strong> аз роҳи нафари, омезиши дақиқии илмӣ ва бозёфтҳои иқтисодист. Ин усул имконияти идоракунии дақиқи ғала, деркунӣ ё хастагардани бемориҳои қозу ва зиёд кардани сифат ва миқдори мҳсулотро таъмин мекунад. Бо назардошти нархҳои лағзишавандаи манбаъҳои об ва ҳатиф дар бозор, сармоягузорӣ дар системаи навтаи обёр даромади назаррас дорад. Кӯшикчиёне, ки дар назарат ғалакунии пайдарпай доранд, метавонанд аз тарҳбандиҳои монанд барои мҳсулоти дигар чун қаламчаҳо <a href="https://navar-abyari.ir/clover-yield-per-hectare-factors-increase/">элитҳо ё набототи шаб</a> (ҳамчун набототи пӯшонишӣ ё чаркунӣ) низ фоида баранд, зеро асосҳои асосии тақсими баробари ғала ва озувӣ, барои ҳамаи мҳсулоти қаторӣ татбиқ мешавад. Охирин, калиди муваффақият, мониторинги доимӣ ва танзими дебит (шараф) оби обёр мувофиқи вазъиятҳои обу ҳаво ва замин аст.</p>\n<p><strong>Мақолаҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%84%d9%88%d8%a8%db%8c%d8%a7-%d9%82%d8%b1%d9%85%d8%b2-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми бӯди гӯдаки сурх дар ҳектар + маслиҳатҳо барои зиёд кардани меҳвар</a></p>','Пурра дастуравии таруни ош бо намоиши қатравона: зиёд кардани ҳосил ва кам кардани талафот','Дар ин мақолаи мукаммал, ба баррасии муфассали ғалтонии палду сӯйи ифодаи системаҳои навини ороиши доғ-доғу ва найраи тез мерасем. аз интихоби бор ва тақсимоти қисмҳои рушдот то дақиқи тайёркунии вақти ороиш, ҳамаи нуқтаҳои зарурӣ барои расидан ба самаранокии баланд ва сифатнокро медонед.','publish','closed','closed','dasturavi-osh-kash-abi-qatava',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
